import { Feather as Icon } from "@expo/vector-icons";
import { useFocusEffect, useNavigation, useRouter } from "expo-router";
import { useCallback, useState } from "react";
import {
  BackHandler,
  FlatList,
  Pressable,
  SafeAreaView,
  StyleSheet,
  Text,
  useWindowDimensions,
  View,
} from "react-native";
import { ActivityCard } from "../components/ui/ActivityCard";
import { ActivitySkeleton } from "../components/ui/ActivitySkeleton";
import { getHorizontalPadding } from "../constants/layout";
import { colors, spacing } from "../constants/theme";
import { useProfile } from "../contexts/ProfileContext";
import { useTheme } from "../contexts/ThemeContext";
import { fetchUserActivity } from "../services/activityService";
import { ActivityItem } from "../types/activity";

export default function ActivityScreen() {
  const { colors: themeColors, isDark } = useTheme();
  const router = useRouter();
  const navigation = useNavigation();
  const { user } = useProfile();
  const { width } = useWindowDimensions();

  const horizontalPadding = getHorizontalPadding(width);
  const maxWidth = Math.min(1100, width - horizontalPadding * 2);

  const [activities, setActivities] = useState<ActivityItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    if (!user) {
      setLoading(false);
      setActivities([]);
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const data = await fetchUserActivity(user.uid);
      setActivities(data);
    } catch (err) {
      console.error("ActivityScreen loadData error:", err);
      setError("Unable to load activity right now. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [user]);

  useFocusEffect(
    useCallback(() => {
      loadData();

      // Android hardware back button handler
      const onBackPress = () => {
        router.replace("/settings" as never);
        return true;
      };

      const subscription = BackHandler.addEventListener(
        "hardwareBackPress",
        onBackPress,
      );

      // Web browser back / navigation stack pop handler
      const unsubscribe = navigation.addListener("beforeRemove", (e: any) => {
        const actionType = e.data?.action?.type;
        if (actionType === "GO_BACK" || actionType === "POP") {
          e.preventDefault();
          router.replace("/settings" as never);
        }
      });

      return () => {
        subscription.remove();
        unsubscribe();
      };
    }, [navigation, router, loadData]),
  );

  const handleCardPress = (item: ActivityItem) => {
    try {
      if (item.type === "lesson") {
        router.push({
          pathname: "/lesson-player",
          params: item.rawDoc
            ? { ...item.rawDoc, source: "activity", returnTo: "/activity" }
            : { id: item.targetId, source: "activity", returnTo: "/activity" },
        } as never);
      } else if (item.type === "page") {
        router.push({
          pathname: "/page-preview",
          params: item.rawDoc
            ? { ...item.rawDoc, source: "activity", returnTo: "/activity" }
            : { id: item.targetId, source: "activity", returnTo: "/activity" },
        } as never);
      } else if (item.type === "book") {
        router.push({
          pathname: "/book-preview",
          params: item.rawDoc
            ? { ...item.rawDoc, source: "activity", returnTo: "/activity" }
            : { id: item.targetId, source: "activity", returnTo: "/activity" },
        } as never);
      }
    } catch (e) {
      console.warn("Navigation error on activity card tap:", e);
    }
  };

  const renderContent = () => {
    // 1. Loading State
    if (loading) {
      return <ActivitySkeleton />;
    }

    // 2. Unauthenticated State
    if (!user) {
      return (
        <View style={styles.emptyContainer}>
          <View style={styles.emptyIconCircle}>
            <Icon name="clock" size={32} color={themeColors.primary} />
          </View>
          <Text style={[styles.emptyTitle, { color: themeColors.text }]}>
            Your activity will appear here
          </Text>
          <Text style={[styles.emptySubtitle, { color: themeColors.subtitle }]}>
            Log in or sign up to keep track of the lessons, pages, and books
            you&apos;ve opened on OS platform.
          </Text>
          <Pressable
            style={({ pressed }) => [
              [styles.primaryButton, { backgroundColor: themeColors.primary }],
              pressed && styles.buttonPressed,
            ]}
            onPress={() => router.push("/welcome" as never)}
            accessibilityRole="button"
            accessibilityLabel="Log in or Sign up"
          >
            <Text
              style={[styles.primaryButtonText, { color: themeColors.white }]}
            >
              Log in or Sign up
            </Text>
          </Pressable>
        </View>
      );
    }

    // 3. Error State
    if (error) {
      return (
        <View style={styles.emptyContainer}>
          <View
            style={[
              styles.emptyIconCircle,
              { backgroundColor: themeColors.dangerBackground },
            ]}
          >
            <Icon name="alert-circle" size={32} color={themeColors.danger} />
          </View>
          <Text style={[styles.emptyTitle, { color: themeColors.text }]}>
            Something went wrong
          </Text>
          <Text style={[styles.emptySubtitle, { color: themeColors.subtitle }]}>
            {error}
          </Text>
          <Pressable
            style={({ pressed }) => [
              [styles.primaryButton, { backgroundColor: themeColors.primary }],
              pressed && styles.buttonPressed,
            ]}
            onPress={loadData}
          >
            <Text
              style={[styles.primaryButtonText, { color: themeColors.white }]}
            >
              Try Again
            </Text>
          </Pressable>
        </View>
      );
    }

    // 4. Authenticated Empty Activity State
    if (activities.length === 0) {
      return (
        <View style={styles.emptyContainer}>
          <View style={styles.emptyIconCircle}>
            <Icon name="book-open" size={32} color={themeColors.primary} />
          </View>
          <Text style={[styles.emptyTitle, { color: themeColors.text }]}>
            No activity yet
          </Text>
          <Text style={[styles.emptySubtitle, { color: themeColors.subtitle }]}>
            Start exploring lessons, books, and academic resources. Your
            recently opened items will appear here.
          </Text>
          <Pressable
            style={({ pressed }) => [
              [styles.primaryButton, { backgroundColor: themeColors.primary }],
              pressed && styles.buttonPressed,
            ]}
            onPress={() => router.push("/" as never)}
            accessibilityRole="button"
            accessibilityLabel="Explore OS platform"
          >
            <Text
              style={[styles.primaryButtonText, { color: themeColors.white }]}
            >
              Explore OS platform
            </Text>
          </Pressable>
        </View>
      );
    }

    // 5. Activity List
    return (
      <FlatList
        data={activities}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <ActivityCard item={item} onPress={() => handleCardPress(item)} />
        )}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.listContent}
      />
    );
  };

  return (
    <SafeAreaView
      style={[styles.safe, { backgroundColor: themeColors.background }]}
    >
      <View style={styles.page}>
        <View style={[styles.contentContainer, { maxWidth }]}>
          {/* Header */}
          <View
            style={[styles.headerRow, { paddingHorizontal: horizontalPadding }]}
          >
            <Pressable
              onPress={() => router.replace("/settings" as never)}
              style={({ pressed }) => [
                styles.backButton,
                pressed && styles.backButtonPressed,
              ]}
              accessibilityRole="button"
              accessibilityLabel="Back to Settings"
            >
              <Icon name="arrow-left" size={22} color={themeColors.text} />
            </Pressable>
            <Text style={[styles.title, { color: themeColors.text }]}>
              Activity
            </Text>
          </View>

          {/* Body Content */}
          <View style={[styles.body, { paddingHorizontal: horizontalPadding }]}>
            {renderContent()}
          </View>
        </View>
      </View>
    </SafeAreaView>
  );
}

