const dateLabel = (value?: { seconds?: number }) =>
  value?.seconds
    ? new Date(value.seconds * 1000).toLocaleString()
    : "Unknown date";

export default function AdminReportsScreen() {
  const { colors: themeColors, isDark } = useTheme();
  const router = useRouter();
  const { profile } = useProfile();
  const { width } = useWindowDimensions();
  const horizontalPadding = getHorizontalPadding(width);
  const maxWidth = Math.min(1100, width - horizontalPadding * 2);
  const [reports, setReports] = useState<ReportRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [notes, setNotes] = useState<Record<string, string>>({});

  const load = useCallback(
    async (isRefresh = false) => {
      if (profile?.type !== "admin") return;
      if (isRefresh) setRefreshing(true);
      else setLoading(true);
      setError(null);
      try {
        const page = await listReports();
        setReports(page.reports);
      } catch (reason) {
        setError(
          reason instanceof Error ? reason.message : "Unable to load reports.",
        );
      } finally {
        setLoading(false);
        setRefreshing(false);
      }
    },
    [profile?.type],
  );

  useFocusEffect(
    useCallback(() => {
      void load();
    }, [load]),
  );

  const saveReport = async (
    report: ReportRecord,
    status: ReportRecord["status"],
  ) => {
    setSavingId(report.id);
    setError(null);
    try {
      await updateReport(
        report.id,
        status,
        notes[report.id] ?? report.adminNotes ?? "",
      );
      setReports((current) =>
        current.map((entry) =>
          entry.id === report.id
            ? {
                ...entry,
                status,
                adminNotes: notes[report.id] ?? entry.adminNotes,
              }
            : entry,
        ),
      );
    } catch (reason) {
      setError(
        reason instanceof Error ? reason.message : "Unable to update report.",
      );
    } finally {
      setSavingId(null);
    }
  };

  if (profile?.type !== "admin") return null;

  return (
    <SafeAreaView
      style={[styles.safe, { backgroundColor: themeColors.background }]}
    >
      <View style={styles.page}>
        <View style={[styles.contentContainer, { maxWidth }]}>
          <ScrollView
            contentContainerStyle={[
              styles.container,
              { paddingHorizontal: horizontalPadding },
            ]}
            style={styles.scroll}
          >
            <View style={styles.header}>
              <Pressable
                onPress={() => router.replace("/settings" as never)}
                accessibilityLabel="Back to settings"
                style={styles.iconButton}
              >
                <Icon name="arrow-left" size={22} color={themeColors.dark} />
              </Pressable>
              <View style={styles.heading}>
                <Text style={[styles.eyebrow, { color: themeColors.primary }]}>
                  ADMIN TOOLS
                </Text>
                <Text style={[styles.title, { color: themeColors.text }]}>
                  Resource reports
                </Text>
              </View>
              <Pressable
                onPress={() => void load(true)}
                accessibilityLabel="Refresh reports"
                style={styles.iconButton}
              >
                <Icon name="refresh-cw" size={18} color={themeColors.primary} />
              </Pressable>
            </View>
            <Text style={[styles.subtitle, { color: themeColors.subtitle }]}>
              Review, track, and resolve reported content.
            </Text>
            {error ? (
              <Text style={[styles.error, { color: themeColors.danger }]}>
                {error}
              </Text>
            ) : null}
            {loading || refreshing ? (
              <View
                style={styles.skeletonList}
                accessibilityLabel="Loading reports"
              >
                {[0, 1, 2].map((item) => (
                  <View
                    key={item}
                    style={[
                      styles.skeletonReport,
                      { backgroundColor: themeColors.white },
                    ]}
                  >
                    <View style={styles.skeletonReportCopy}>
                      <Skeleton style={styles.skeletonTitle} />
                      <Skeleton style={styles.skeletonLine} />
                    </View>
                    <Skeleton style={styles.skeletonStatus} />
                  </View>
                ))}
              </View>
            ) : null}
            {!loading && !reports.length ? (
              <Text style={[styles.empty, { color: themeColors.subtitle }]}>
                No reports yet.
              </Text>
            ) : null}
            {reports.map((report) => (
              <View
                key={report.id}
                style={[
                  styles.report,
                  {
                    backgroundColor: themeColors.white,
                    borderColor: themeColors.border,
                  },
                ]}
              >
                <View style={styles.reportHeader}>
                  <View style={styles.reportTitleWrap}>
                    <Text
                      style={[styles.reportTitle, { color: themeColors.text }]}
                    >
                      {report.item.name}
                    </Text>
                    <Text
                      style={[styles.meta, { color: themeColors.subtitle }]}
                    >
                      {report.item.type} ┬╖ {dateLabel(report.createdAt)}
                    </Text>
                  </View>
                  <Text
                    style={[
                      styles.status,
                      report.status === "resolved" && styles.resolved,
                      report.status === "dismissed" && styles.dismissed,
                    ]}
                  >
                    {report.status}
                  </Text>
                </View>
                <Text style={[styles.body, { color: themeColors.text }]}>
                  Problems: {report.reasons?.join(", ") || "None selected"}
                </Text>
                <Text style={[styles.body, { color: themeColors.text }]}>
                  {report.details || "No written details."}
                </Text>
                <Text style={[styles.meta, { color: themeColors.subtitle }]}>
                  By {report.username} ┬╖ {report.userEmail}
                </Text>
                <Text style={[styles.meta, { color: themeColors.subtitle }]}>
                  Item ID: {report.item.id} ┬╖ User ID: {report.userId}
                </Text>
                <View style={styles.statusActions}>
                  {(
                    [
                      "new",
                      "in_review",
                      "resolved",
                      "dismissed",
                    ] as ReportRecord["status"][]
                  ).map((status) => (
                    <Pressable
                      key={status}
                      onPress={() => void saveReport(report, status)}
                      disabled={savingId === report.id}
                      style={[
                        styles.statusButton,
                        { borderColor: themeColors.border },
                        report.status === status && styles.statusButtonSelected,
                        report.status === status && {
                          backgroundColor: themeColors.primaryLight,
                          borderColor: themeColors.primary,
                        },
                      ]}
                    >
                      <Text
                        style={[
                          styles.statusButtonText,
                          {
                            color:
                              report.status === status
                                ? themeColors.primary
                                : themeColors.text,
                          },
                        ]}
                      >
                        {status.replace("_", " ")}
                      </Text>
                    </Pressable>
                  ))}
                </View>
                <TextInput
                  value={notes[report.id] ?? report.adminNotes ?? ""}
                  onChangeText={(value) =>
                    setNotes((current) => ({ ...current, [report.id]: value }))
                  }
                  placeholder="Add an internal admin note"
                  placeholderTextColor={themeColors.subtitle}
                  multiline
                  maxLength={2000}
                  style={[
                    styles.notesInput,
                    {
                      borderColor: themeColors.border,
                      color: themeColors.text,
                    },
                  ]}
                />
              </View>
            ))}
          </ScrollView>
        </View>
      </View>
    </SafeAreaView>
  );
}

