import { Feather, FontAwesome } from "@expo/vector-icons";
import { useLocalSearchParams, useRouter } from "expo-router";
import { signOut } from "firebase/auth";
import { useCallback, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  useWindowDimensions,
  View,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { auth } from "../../firebaseConfig";
import { ActionDialog } from "../components/ui/ActionDialog";
import { getHorizontalPadding } from "../constants/layout";
import { colors, spacing } from "../constants/theme";
import { useTheme } from "../contexts/ThemeContext";
import { sendEmailLink } from "../services/emailLinkAuth";
import {
  parseAuthError,
  signInWithFacebook,
  signInWithGoogle,
} from "../services/socialAuth";

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MAX_EMAIL_LENGTH = 50;

function mapAuthError(code: string | undefined) {
  switch (code) {
    case "auth/invalid-email":
      return "Please enter a valid email address.";
    case "auth/user-not-found":
      return "No account found with this email. Try signing up.";
    case "auth/too-many-requests":
      return "Too many attempts. Please try again later.";
    case "auth/network-request-failed":
      return "Couldn't connect. Check your internet and try again.";
    case "auth/user-disabled":
      return "This account has been disabled. Contact support.";
    case "auth/popup-closed-by-user":
    case "auth/cancelled-popup-request":
      return "Authentication was cancelled.";
    default:
      return "Something went wrong. Please try again.";
  }
}

export default function LoginScreen() {
  const { colors: themeColors } = useTheme();
  const router = useRouter();
  const { from } = useLocalSearchParams<{ from?: string }>();
  const { width } = useWindowDimensions();
  const emailInputRef = useRef<TextInput>(null);
  const [email, setEmail] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showLogoutDialog, setShowLogoutDialog] = useState(false);
  const [emailError, setEmailError] = useState("");
  const [generalError, setGeneralError] = useState("");

  const horizontalPadding = useMemo(() => getHorizontalPadding(width), [width]);
  const contentMaxWidth = Math.min(520, width - horizontalPadding * 2);

  const validateFields = useCallback(() => {
    const trimmedEmail = email.trim();
    let hasError = false;

    if (!trimmedEmail) {
      setEmailError("Please enter your email address.");
      hasError = true;
    } else if (trimmedEmail.length > MAX_EMAIL_LENGTH) {
      setEmailError(`Email must be ${MAX_EMAIL_LENGTH} characters or fewer.`);
      hasError = true;
    } else if (!EMAIL_REGEX.test(trimmedEmail)) {
      setEmailError("Please enter a valid email address.");
      hasError = true;
    } else {
      setEmailError("");
    }

    return !hasError;
  }, [email]);

  const handleContinue = useCallback(async () => {
    if (isLoading) return;

    setGeneralError("");

    if (!validateFields()) return;

    try {
      setIsLoading(true);
      await sendEmailLink(email);
      router.replace({
        pathname: "/verify-email",
        params: { next: "/", email: email.trim() },
      });
    } catch (error) {
      const code =
        typeof error === "object" && error !== null && "code" in error
          ? (error as any).code
          : undefined;
      const message = mapAuthError(code);

      if (code === "auth/invalid-email") {
        setEmailError(message);
      } else {
        setGeneralError(message);
      }
    } finally {
      setIsLoading(false);
    }
  }, [email, isLoading, router, validateFields]);

  const handleGoogleSignIn = useCallback(async () => {
    if (isLoading) return;
    setGeneralError("");
    setIsLoading(true);

    try {
      const result = await signInWithGoogle();
      if (result.cancelled) {
        return;
      }
      if (result.success && result.user) {
        router.dismissAll();
        router.replace("/");
      } else if (result.error) {
        setGeneralError(result.error);
      }
    } catch (error) {
      setGeneralError(parseAuthError(error));
    } finally {
      setIsLoading(false);
    }
  }, [isLoading, router]);

  const handleFacebookSignIn = useCallback(async () => {
    if (isLoading) return;
    setGeneralError("");
    setIsLoading(true);

    try {
      const result = await signInWithFacebook();
      if (result.cancelled) {
        return;
      }
      if (result.success && result.user) {
        router.dismissAll();
        router.replace("/");
      } else if (result.error) {
        setGeneralError(result.error);
      }
    } catch (error) {
      setGeneralError(parseAuthError(error));
    } finally {
      setIsLoading(false);
    }
  }, [isLoading, router]);

  const handleEmailIcon = useCallback(() => {
    if (email.trim()) {
      handleContinue();
    } else {
      emailInputRef.current?.focus();
    }
  }, [email, handleContinue]);

  const handleBack = useCallback(() => {
    if (router.canGoBack()) {
      router.back();
      return;
    }

    if (typeof from === "string" && from.trim()) {
      router.replace(from as any);
    }
  }, [router, from]);

  const handleLogout = useCallback(async () => {
    try {
      await signOut(auth);
      router.replace("/");
    } catch {
      setShowLogoutDialog(false);
    }
  }, [router]);

  const currentUser = auth.currentUser;

  if (currentUser) {
    return (
      <SafeAreaView
        style={[styles.safeArea, { backgroundColor: themeColors.background }]}
      >
        <ActionDialog
          visible={showLogoutDialog}
          title="Unable to sign out"
          message="Please try again."
          primaryText="OK"
          onPrimary={() => setShowLogoutDialog(false)}
          onClose={() => setShowLogoutDialog(false)}
        />
        <View
          style={[
            styles.container,
            { paddingHorizontal: horizontalPadding, maxWidth: contentMaxWidth },
          ]}
        >
          <View style={styles.headerWithBack}>
            <Pressable
              onPress={handleBack}
              style={styles.backButton}
              accessibilityRole="button"
              accessibilityLabel="Go back"
            >
              <Feather name="arrow-left" size={22} color={themeColors.text} />
            </Pressable>
            <Text style={[styles.title, { color: themeColors.text }]}>
              You&apos;re already signed in
            </Text>
          </View>

          <Text style={[styles.subtitle, { color: themeColors.subtitle }]}>
            You&apos;re already signed in to OS platform. You can continue
            learning or log out to switch accounts.
          </Text>

          <View style={styles.form}>
            <Pressable
              onPress={() => router.replace("/")}
              style={styles.continueButton}
              accessibilityRole="button"
            >
              <Text style={styles.continueButtonText}>Go to OS platform</Text>
            </Pressable>

            <Pressable
              onPress={() => setShowLogoutDialog(true)}
              style={[
                styles.continueButton,
                {
                  backgroundColor: colors.white,
                  borderWidth: 1,
                  borderColor: themeColors.border,
                },
              ]}
              accessibilityRole="button"
            >
              <Text
                style={[styles.continueButtonText, { color: themeColors.text }]}
              >
                Log out
              </Text>
            </Pressable>
          </View>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView
      style={[styles.safeArea, { backgroundColor: themeColors.background }]}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.keyboardArea}
        keyboardVerticalOffset={Platform.OS === "ios" ? 90 : 60}
      >
        <ScrollView
          contentContainerStyle={[
            styles.scrollContent,
            { paddingHorizontal: horizontalPadding },
          ]}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <View style={[styles.container, { maxWidth: contentMaxWidth }]}>
            <View style={styles.headerWithBack}>
              <Pressable
                onPress={handleBack}
                style={styles.backButton}
                accessibilityRole="button"
                accessibilityLabel="Go back"
              >
                <Feather name="arrow-left" size={22} color={themeColors.text} />
              </Pressable>
              <Text style={[styles.title, { color: themeColors.text }]}>
                Log In
              </Text>
            </View>

            <Text style={[styles.subtitle, { color: themeColors.subtitle }]}>
              Fill your information or continue with your{"\n"}social accounts
            </Text>

            <View style={styles.form}>
              <View style={styles.fieldGroup}>
                <Text style={[styles.fieldLabel, { color: themeColors.text }]}>
                  Email
                </Text>
                <TextInput
                  ref={emailInputRef}
                  value={email}
                  onChangeText={setEmail}
                  maxLength={MAX_EMAIL_LENGTH}
                  keyboardType="email-address"
                  autoCapitalize="none"
                  autoCorrect={false}
                  placeholder="your@email.com"
                  placeholderTextColor={themeColors.subtitle}
                  style={[
                    styles.input,
                    {
                      backgroundColor: themeColors.white,
                      borderColor: themeColors.border,
                      color: themeColors.text,
                    },
                    emailError ? styles.inputError : null,
                  ]}
                  textContentType="emailAddress"
                  accessibilityLabel="Email"
                  accessibilityHint="Enter your email address"
                />
                {emailError ? (
                  <Text
                    style={[
                      styles.fieldError,
                      { color: themeColors.primaryRed },
                    ]}
                  >
                    {emailError}
                  </Text>
                ) : null}
              </View>

              {generalError ? (
                <Text
                  style={[
                    styles.generalError,
                    { color: themeColors.primaryRed },
                  ]}
                >
                  {generalError}
                </Text>
              ) : null}

              <Pressable
                onPress={handleContinue}
                disabled={isLoading}
                style={({ pressed }) => [
                  styles.continueButton,
                  isLoading && styles.continueButtonDisabled,
                  pressed && !isLoading && styles.buttonPressed,
                ]}
                accessibilityRole="button"
                accessibilityLabel="Send email sign-in link"
              >
                {isLoading ? (
                  <ActivityIndicator color={colors.white} />
                ) : (
                  <Text style={styles.continueButtonText}>
                    Send sign-in link
                  </Text>
                )}
              </Pressable>
            </View>

            <View style={styles.dividerRow}>
              <View
                style={[
                  styles.dividerLine,
                  { backgroundColor: themeColors.border },
                ]}
              />
              <Text
                style={[styles.dividerText, { color: themeColors.subtitle }]}
              >
                OR LOG IN WITH
              </Text>
              <View
                style={[
                  styles.dividerLine,
                  { backgroundColor: themeColors.border },
                ]}
              />
            </View>

            <View style={styles.socialRow}>
              <Pressable
                onPress={handleGoogleSignIn}
                style={({ pressed }) => [
                  styles.socialButton,
                  {
                    backgroundColor: themeColors.white,
                    borderColor: themeColors.border,
                  },
                  pressed && styles.socialPressed,
                ]}
                disabled={isLoading}
                accessibilityRole="button"
                accessibilityLabel="Sign in with Google"
              >
                <FontAwesome name="google" size={20} color="#EA4335" />
              </Pressable>

              <Pressable
                onPress={handleFacebookSignIn}
                style={({ pressed }) => [
                  styles.socialButton,
                  {
                    backgroundColor: themeColors.white,
                    borderColor: themeColors.border,
                  },
                  pressed && styles.socialPressed,
                ]}
                disabled={isLoading}
                accessibilityRole="button"
                accessibilityLabel="Sign in with Facebook"
              >
                <FontAwesome name="facebook" size={20} color="#1877F2" />
              </Pressable>

              <Pressable
                onPress={handleEmailIcon}
                style={({ pressed }) => [
                  styles.socialButton,
                  {
                    backgroundColor: themeColors.white,
                    borderColor: themeColors.border,
                  },
                  pressed && styles.socialPressed,
                ]}
                disabled={isLoading}
                accessibilityRole="button"
                accessibilityLabel="Continue with email"
              >
                <Feather name="mail" size={20} color={themeColors.text} />
              </Pressable>
            </View>

            <View style={styles.footerRow}>
              <Text style={[styles.footerText, { color: themeColors.text }]}>
                Don&apos;t have an account?
              </Text>
              <Pressable
                onPress={() =>
                  router.push({
                    pathname: "/signup",
                    params: {
                      from:
                        typeof from === "string" && from.trim() ? from : "/",
                    },
                  })
                }
                accessibilityRole="button"
                accessibilityLabel="Sign up for OS platform"
              >
                <Text style={styles.footerLink}>Sign up</Text>
              </Pressable>
            </View>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

