import { Feather } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import { doc, updateDoc } from "firebase/firestore";
import { useCallback, useEffect, useRef, useState } from "react";
import {
    ActivityIndicator,
    Pressable,
    SafeAreaView,
    ScrollView,
    StyleSheet,
    Text,
    useWindowDimensions,
    View,
} from "react-native";
import { db } from "../../firebaseConfig";
import { NotifyToggle } from "../components/library/add-item/SharedFormControls";
import { Skeleton } from "../components/ui/Skeleton";
import { getHorizontalPadding } from "../constants/layout";
import { colors, spacing } from "../constants/theme";
import { useProfile } from "../contexts/ProfileContext";
import { useTheme } from "../contexts/ThemeContext";
import { loadSubjects as loadCachedSubjects } from "../services/subjectsService";

type Subject = { id: string; name: string };

function PreferenceChip({
  name,
  selected,
  onPress,
}: {
  name: string;
  selected: boolean;
  onPress: () => void;
}) {
  const { colors: themeColors } = useTheme();
  return (
    <Pressable
      onPress={onPress}
      style={({ pressed }) => [
        styles.chip,
        { backgroundColor: themeColors.white, borderColor: themeColors.border },
        selected && styles.chipSelected,
        pressed && styles.chipPressed,
      ]}
      accessibilityRole="checkbox"
      accessibilityState={{ checked: selected }}
      accessibilityLabel={`${name}, ${selected ? "selected" : "not selected"}`}
    >
      <Text
        style={[
          styles.chipText,
          { color: selected ? themeColors.white : themeColors.text },
          selected && styles.chipTextSelected,
        ]}
      >
        {name}
      </Text>
    </Pressable>
  );
}

function AuthPrompt() {
  const router = useRouter();
  const { colors: themeColors } = useTheme();
  return (
    <View style={styles.authPrompt}>
      <Feather name="sliders" size={32} color={themeColors.primary} />
      <Text style={[styles.authTitle, { color: themeColors.dark }]}>
        Personalize your learning
      </Text>
      <Text style={[styles.authCopy, { color: themeColors.subtitle }]}>
        Sign in or create an OS platform account to choose your subjects and get
        a more personalized learning experience.
      </Text>
      <View style={styles.authActions}>
        <Pressable
          onPress={() =>
            router.push({
              pathname: "/login",
              params: { from: "preferences" },
            } as never)
          }
          style={[styles.login, { borderColor: themeColors.primary }]}
        >
          <Text style={[styles.loginText, { color: themeColors.primary }]}>
            Log in
          </Text>
        </Pressable>
        <Pressable
          onPress={() => router.push("/signup" as never)}
          style={[styles.signup, { backgroundColor: themeColors.primary }]}
        >
          <Text style={[styles.signupText, { color: themeColors.white }]}>
            Sign up
          </Text>
        </Pressable>
      </View>
    </View>
  );
}

export default function PreferencesScreen() {
  const { colors: themeColors, isDark } = useTheme();
  const router = useRouter();
  const { width } = useWindowDimensions();
  const { user, profile, loading: profileLoading } = useProfile();

  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [selected, setSelected] = useState<string[]>([]);
  const [filterFeedByInterests, setFilterFeedByInterests] = useState(false);
  const [loadingSubjects, setLoadingSubjects] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [saveError, setSaveError] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const initialized = useRef(false);
  const horizontalPadding = getHorizontalPadding(width);
  const maxWidth = Math.min(1100, width - horizontalPadding * 2);

  const loadSubjects = useCallback(async () => {
    setLoadingSubjects(true);
    setLoadError(false);
    try {
      const available = await loadCachedSubjects();
      setSubjects(available.map(({ id, name }) => ({ id, name })));
    } catch {
      setLoadError(true);
    } finally {
      setLoadingSubjects(false);
    }
  }, []);

  useEffect(() => {
    void Promise.resolve().then(() => loadSubjects());
  }, [loadSubjects]);

  useEffect(() => {
    if (!initialized.current && !profileLoading) {
      setFilterFeedByInterests(Boolean(profile?.filterFeedByInterests));
      const seen = new Set<string>();
      setSelected(
        (profile?.subjects ?? []).reduce<string[]>((result, name) => {
          const clean = typeof name === "string" ? name.trim() : "";
          const key = clean.toLocaleLowerCase();
          if (clean && !seen.has(key)) {
            seen.add(key);
            result.push(clean);
          }
          return result;
        }, []),
      );
      initialized.current = true;
    }
  }, [profile?.subjects, profile?.filterFeedByInterests, profileLoading]);

  const toggle = (name: string) =>
    setSelected((current) =>
      current.some(
        (item) =>
          item.localeCompare(name, undefined, { sensitivity: "accent" }) === 0,
      )
        ? current.filter(
            (item) =>
              item.localeCompare(name, undefined, { sensitivity: "accent" }) !==
              0,
          )
        : [...current, name],
    );

  const arraysEqualIgnoreOrder = (a: string[], b: any[]) => {
    const norm = (arr: any[]) =>
      arr
        .map((s) => String(s).trim().toLowerCase())
        .filter(Boolean)
        .sort();
    const A = norm(a);
    const B = norm(b);
    if (A.length !== B.length) return false;
    for (let i = 0; i < A.length; i++) if (A[i] !== B[i]) return false;
    return true;
  };

  const save = async () => {
    if (!user || saving) return;
    const originalSubjects = profile?.subjects ?? [];
    const originalFilter = Boolean(profile?.filterFeedByInterests);
    if (
      arraysEqualIgnoreOrder(selected, originalSubjects) &&
      filterFeedByInterests === originalFilter
    ) {
      setSaved(true);
      return;
    }
    try {
      setSaving(true);
      setSaved(false);
      setSaveError(false);
      const collectionName = profile?.type === "teacher" ? "teachers" : "users";
      await updateDoc(doc(db, collectionName, user.uid), {
        subjects: selected,
        filterFeedByInterests,
      });
      setSaved(true);
    } catch {
      setSaveError(true);
    } finally {
      setSaving(false);
    }
  };

  const isLoading = profileLoading || loadingSubjects;

  return (
    <SafeAreaView
      style={[styles.safe, { backgroundColor: themeColors.background }]}
    >
      <View style={styles.page}>
        <View style={[styles.contentContainer, { maxWidth }]}>
          <ScrollView
            contentContainerStyle={[
              styles.container,
              { paddingHorizontal: horizontalPadding },
            ]}
            showsVerticalScrollIndicator={false}
          >
            <View style={styles.header}>
              <View style={styles.headerRow}>
                <Pressable
                  onPress={() => router.replace("/settings" as never)}
                  style={styles.backButton}
                  accessibilityLabel="Back to profile"
                >
                  <Feather
                    name="chevron-left"
                    size={22}
                    color={themeColors.text}
                  />
                </Pressable>
                <Text style={[styles.title, { color: themeColors.text }]}>
                  Preferences
                </Text>
              </View>
              {user ? (
                <Pressable
                  onPress={save}
                  disabled={saving || isLoading}
                  style={styles.saveButton}
                  accessibilityLabel="Save preferences"
                >
                  {saving ? (
                    <ActivityIndicator
                      size="small"
                      color={themeColors.primary}
                    />
                  ) : (
                    <Text
                      style={[
                        styles.saveText,
                        { color: themeColors.primary },
                        isLoading && styles.disabled,
                      ]}
                    >
                      Save
                    </Text>
                  )}
                </Pressable>
              ) : (
                <View style={styles.headerButton} />
              )}
            </View>

            {!user && !profileLoading ? (
              <AuthPrompt />
            ) : isLoading ? (
              <View style={styles.skeleton}>
                <Skeleton style={styles.skeletonText} />
                <Skeleton style={styles.skeletonHeading} />
                <View style={styles.skeletonChips}>
                  {[0, 1, 2, 3, 4].map((item) => (
                    <Skeleton key={item} style={styles.skeletonChip} />
                  ))}
                </View>
              </View>
            ) : loadError ? (
              <View style={styles.error}>
                <Text style={[styles.errorTitle, { color: themeColors.text }]}>
                  We couldnΓÇÖt load preferences.
                </Text>
                <Text
                  style={[styles.errorCopy, { color: themeColors.subtitle }]}
                >
                  Check your connection and try again.
                </Text>
                <Pressable onPress={loadSubjects} style={styles.retry}>
                  <Text style={styles.retryText}>Try again</Text>
                </Pressable>
              </View>
            ) : (
              <>
                <Text style={[styles.helper, { color: themeColors.subtitle }]}>
                  Choose the subjects you&apos;re interested in to personalize
                  your home feed, recommendations, and learning resources.
                </Text>

                <Text
                  style={[styles.sectionTitle, { color: themeColors.dark }]}
                >
                  My Subjects
                </Text>
                {subjects.length ? (
                  <View style={styles.chips}>
                    {subjects.map((subject) => (
                      <PreferenceChip
                        key={subject.id}
                        name={subject.name}
                        selected={selected.some(
                          (item) =>
                            item.toLocaleLowerCase() ===
                            subject.name.toLocaleLowerCase(),
                        )}
                        onPress={() => toggle(subject.name)}
                      />
                    ))}
                  </View>
                ) : (
                  <View style={styles.empty}>
                    <Text
                      style={[styles.emptyTitle, { color: themeColors.text }]}
                    >
                      No subjects available yet.
                    </Text>
                    <Text
                      style={[
                        styles.emptyCopy,
                        { color: themeColors.subtitle },
                      ]}
                    >
                      We&apos;re preparing more subjects for you.
                    </Text>
                  </View>
                )}
                {saved ? (
                  <Text
                    style={[styles.success, { color: themeColors.success }]}
                  >
                    Preferences saved.
                  </Text>
                ) : null}
                {saveError ? (
                  <Text
                    style={[
                      styles.saveError,
                      { color: themeColors.primaryRed },
                    ]}
                  >
                    Couldn&apos;t save preferences. Please try again.
                  </Text>
                ) : null}
              </>
            )}

            <View
              style={[
                styles.toggleCard,
                {
                  backgroundColor: themeColors.lightBackground,
                  borderColor: themeColors.border,
                },
              ]}
            >
              <View style={styles.toggleInfo}>
                <Text style={[styles.toggleTitle, { color: themeColors.text }]}>
                  Only show selected interests in feeds
                </Text>
                <Text
                  style={[
                    styles.toggleSubtitle,
                    { color: themeColors.subtitle },
                  ]}
                >
                  Filter your Home and Library feeds to only display resources
                  matching your selected subjects.
                </Text>
              </View>
              <NotifyToggle
                checked={filterFeedByInterests}
                onToggle={() => setFilterFeedByInterests((value) => !value)}
                accessibilityLabel="Toggle filter feeds by interests"
              />
            </View>

            <View style={{ height: 60 }} />
          </ScrollView>
        </View>
      </View>
    </SafeAreaView>
  );
}

