const gradients = [
  ["#57F287", "#2D9CFF"],
  ["#6A5AF9", "#D66BFF"],
  ["#FF6A88", "#FFB86B"],
  ["#00C9A7", "#0084FF"],
  ["#F857A6", "#FF5858"],
  ["#4FACFE", "#00F2FE"],
] as const;

const strings = (v: unknown) =>
  Array.isArray(v)
    ? v.filter((x): x is string => typeof x === "string")
    : typeof v === "string"
      ? [v]
      : [];

const asNumber = (v: unknown) =>
  typeof v === "number"
    ? v
    : typeof v === "string"
      ? Number(v) || undefined
      : undefined;

function mapBook(id: string, d: Record<string, unknown>): Book {
  return {
    id,
    title: typeof d.title === "string" ? d.title : "Untitled book",
    description:
      typeof d.description === "string"
        ? d.description
        : typeof d.summary === "string"
          ? d.summary
          : "",
    cover:
      typeof d.cover === "string" && d.cover.trim()
        ? d.cover.trim()
        : typeof d.image === "string" && d.image.trim()
          ? d.image.trim()
          : "",
    sampleUri:
      typeof d.sampleUri === "string"
        ? d.sampleUri.trim()
        : typeof d.previewUrl === "string"
          ? d.previewUrl.trim()
          : typeof d.sampleUrl === "string"
            ? d.sampleUrl.trim()
            : typeof d.pdfUrl === "string"
              ? d.pdfUrl.trim()
              : undefined,
    year:
      typeof d.year === "string" || typeof d.year === "number"
        ? String(d.year)
        : undefined,
    edition: typeof d.edition === "string" ? d.edition : undefined,
    author: strings(d.author),
    subject: strings(d.subject),
    pages:
      typeof d.pages === "string" || typeof d.pages === "number"
        ? String(d.pages)
        : typeof d.pageCount === "number"
          ? String(d.pageCount)
          : undefined,
    rating: asNumber(d.rating),
    saves: asNumber(d.savedBy ?? d.saves),
  };
}

export function BookPreviewScreen() {
  const { colors: themeColors } = useTheme();
  const { id, source, returnTo, teacherId, teacherName } =
    useLocalSearchParams<{
      id: string;
      source?: string;
      returnTo?: string;
      teacherId?: string;
      teacherName?: string;
    }>();
  const [book, setBook] = useState<Book>();
  const [allBooks, setAllBooks] = useState<Book[]>([]);
  const [teacherAvatars, setTeacherAvatars] = useState<Record<string, string>>(
    {},
  );
  const [teacherPhones, setTeacherPhones] = useState<Record<string, string>>(
    {},
  );
  const [defaultUserAvatar, setDefaultUserAvatar] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const [showGuestSaveAlert, setShowGuestSaveAlert] = useState(false);
  const [showGetYoursDialog, setShowGetYoursDialog] = useState(false);

  const [bookmarked, setBookmarked] = useState(false);
  const { width } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const horizontalPadding = getHorizontalPadding(width);
  const contentMaxWidth = Math.min(1100, width - horizontalPadding * 2);
  const [gradient] = useState(
    () => gradients[Math.floor(Math.random() * gradients.length)],
  );

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      try {
        if (auth.currentUser?.uid && id) {
          recordUserActivity(auth.currentUser.uid, "book", id);
        }
        void recordBookVisit(id);

        const [selected, booksSnapshot, teachersSnapshot, defaultSnapshot] =
          await Promise.all([
            getDoc(doc(db, "books", id)),
            readThroughFirestoreCache("collection:books", () =>
              getDocs(collection(db, "books")),
            ),
            readThroughFirestoreCache("collection:teachers", () =>
              getDocs(collection(db, "teachers")),
            ),
            readThroughFirestoreCache("collection:default", () =>
              getDocs(collection(db, "default")),
            ),
          ]);

        if (!active) return;

        if (!selected.exists()) {
          setBook(undefined);
          setAllBooks([]);
          return;
        }

        // Extract default user avatar from 'default' collection
        let defaultAvatar = "";
        defaultSnapshot.docs.forEach((docSnap) => {
          const data = docSnap.data();
          const docName =
            typeof data.name === "string" ? normalizeKey(data.name) : "";
          if (docName === "user" && typeof data.icon === "string") {
            defaultAvatar = data.icon.trim();
          }
        });
        setDefaultUserAvatar(defaultAvatar);

        // Map teacher names (normalized lowercase) to their avatar URLs and phone numbers
        const avatarsMap: Record<string, string> = {};
        const phonesMap: Record<string, string> = {};
        teachersSnapshot.docs.forEach((docSnap) => {
          const data = docSnap.data();
          if (typeof data.name === "string") {
            const key = normalizeKey(data.name);
            if (typeof data.avatar === "string") {
              avatarsMap[key] = data.avatar.trim();
            }
            if (typeof data.phone === "string" && data.phone.trim()) {
              phonesMap[key] = data.phone.trim();
            }
          }
        });
        setTeacherAvatars(avatarsMap);
        setTeacherPhones(phonesMap);

        // Set Book Data
        setBook(
          mapBook(selected.id, selected.data() as Record<string, unknown>),
        );
        setAllBooks(
          booksSnapshot.docs.map((d) =>
            mapBook(d.id, d.data() as Record<string, unknown>),
          ),
        );
      } catch (e) {
        console.error("Could not load book preview", e);
        if (active) {
          setBook(undefined);
          setAllBooks([]);
        }
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => {
      active = false;
    };
  }, [id]);

  // Check if book is bookmarked and load bookmarked state
  useEffect(() => {
    if (!book || !auth.currentUser?.uid) return;

    const checkBookmarked = async () => {
      try {
        const profile = await getSavedItemsProfile(auth.currentUser!.uid);
        if (profile) {
          const savedBooks = Array.isArray(profile["saved-books"])
            ? profile["saved-books"]
            : [];
          setBookmarked(savedBooks.includes(book.id));
        }
      } catch (e) {
        console.error("Failed to check bookmark status", e);
      }
    };

    checkBookmarked();
  }, [book?.id]);

  const authorsWithAvatars = useMemo(() => {
    if (!book) return [];
    return book.author.map((authorName) => ({
      name: authorName,
      avatar: resolveAuthorAvatar(
        authorName,
        teacherAvatars,
        defaultUserAvatar,
      ),
    }));
  }, [book, teacherAvatars, defaultUserAvatar]);

  const similar = useMemo(
    () =>
      book
        ? allBooks
            .filter(
              (candidate) =>
                candidate.id !== book.id &&
                candidate.subject.some((subject) =>
                  book.subject.some(
                    (bookSubject) =>
                      normalizeKey(bookSubject) === normalizeKey(subject),
                  ),
                ),
            )
            .sort((a, b) => (b.saves ?? 0) - (a.saves ?? 0))
            .slice(0, 10)
        : [],
    [allBooks, book],
  );

  const openSample = () => {
    if (!book?.sampleUri) return;
    router.push({
      pathname: "/pdf-reader",
      params: { uri: book.sampleUri, title: book.title, pageId: book.id },
    } as any);
  };

  if (loading)
    return (
      <View
        style={[styles.loading, { backgroundColor: themeColors.background }]}
        accessibilityLabel="Loading book preview"
      >
        <View
          style={[
            styles.contentContainer,
            {
              maxWidth: contentMaxWidth,
              paddingHorizontal: horizontalPadding,
            },
          ]}
        >
          <Skeleton
            style={[
              styles.skeletonHero,
              { backgroundColor: themeColors.surfaceMuted },
            ]}
          />
          <View
            style={[
              styles.skeletonSheet,
              { backgroundColor: themeColors.surface },
            ]}
          >
            <Skeleton
              style={[
                styles.skeletonTitle,
                { backgroundColor: themeColors.surfaceMuted },
              ]}
            />
            <Skeleton
              style={[
                styles.skeletonLine,
                { backgroundColor: themeColors.surfaceMuted },
              ]}
            />
            <Skeleton
              style={[
                styles.skeletonLineShort,
                { backgroundColor: themeColors.surfaceMuted },
              ]}
            />
            <Skeleton
              style={[
                styles.skeletonAvatars,
                { backgroundColor: themeColors.surfaceMuted },
              ]}
            />
          </View>
        </View>
      </View>
    );

  if (!book) {
    return (
      <View
        style={[styles.loading, { backgroundColor: themeColors.background }]}
      >
        <MissingResourceDialog
          resourceType="book"
          resourceId={id}
          resourceName="Book"
          onGoBack={() => router.back()}
        />
      </View>
    );
  }
  const goBack = () => {
    if (typeof returnTo === "string" && returnTo.trim() === "/profile") {
      router.back();
      return;
    }

    if (
      typeof returnTo === "string" &&
      returnTo.trim() === "/teacher-profile" &&
      ((typeof teacherId === "string" && teacherId.trim()) ||
        (typeof teacherName === "string" && teacherName.trim()))
    ) {
      if (router.canGoBack()) {
        router.back();
        return;
      }

      router.replace({
        pathname: "/teacher-profile",
        params: {
          ...(typeof teacherId === "string" && teacherId.trim()
            ? { id: teacherId.trim() }
            : {}),
          ...(typeof teacherName === "string" && teacherName.trim()
            ? { name: teacherName.trim() }
            : {}),
        },
      } as any);
      return;
    }

    if (
      typeof returnTo === "string" &&
      returnTo.trim() === "/library" &&
      router.canGoBack()
    ) {
      router.back();
      return;
    }

    if (typeof returnTo === "string" && returnTo.trim()) {
      router.replace(returnTo as any);
      return;
    }

    // Fallback based on source
    switch (source) {
      case "home":
        router.replace("/" as any);
        break;
      case "saved":
        router.replace("/profile" as any);
        break;
      case "activity":
        router.replace("/activity" as any);
        break;
      case "notifications":
        router.replace("/notifications" as any);
        break;
      case "search":
        if (router.canGoBack()) {
          router.back();
        } else {
          router.replace("/(search)/search" as any);
        }
        break;
      default:
        router.replace("/library" as any);
    }
  };

  return (
    <Animated.View
      key={id}
      entering={FadeIn.duration(260)}
      style={[
        styles.screen,
        { alignItems: "center", backgroundColor: themeColors.background },
      ]}
    >
      <View style={[styles.contentContainer, { maxWidth: contentMaxWidth }]}>
        <ScrollView
          showsVerticalScrollIndicator={false}
          contentContainerStyle={[
            styles.scrollContent,
            {
              paddingBottom: 120 + insets.bottom,
              paddingHorizontal: horizontalPadding,
            },
          ]}
        >
          <BookHero book={book} onBack={goBack} />
          <Animated.View
            entering={FadeInUp.duration(430)}
            style={[
              styles.sheet,
              { paddingHorizontal: 10, backgroundColor: themeColors.surface },
            ]}
          >
            <BookQuickInfo book={book} />
            <BookOverview book={book} />
            <AuthorsCarousel
              authors={authorsWithAvatars}
              onAuthorPress={(name) =>
                router.push({
                  pathname: "/teacher-profile",
                  params: { name },
                } as any)
              }
            />
            <SimilarBooks
              books={similar}
              onSelect={(nextId) =>
                router.replace({
                  pathname: "/book-preview",
                  params: {
                    id: nextId,
                    source: source ?? "library",
                    returnTo:
                      typeof returnTo === "string"
                        ? returnTo
                        : source === "home"
                          ? "/"
                          : "/library",
                  },
                } as any)
              }
            />
          </Animated.View>
        </ScrollView>
      </View>
      <View
        style={[
          styles.action,
          {
            backgroundColor: themeColors.white,
            left: horizontalPadding,
            right: horizontalPadding,
          },
        ]}
      >
        <View
          style={[
            styles.actionContent,
            {
              maxWidth: contentMaxWidth,
              paddingHorizontal: horizontalPadding,
              paddingBottom: Math.max(insets.bottom, 10),
            },
          ]}
        >
          <BottomActionBar
            gradient={gradient}
            bookmarked={bookmarked}
            onPreview={book.sampleUri ? openSample : undefined}
            onGetYours={() => {
              const phone = book.author.length
                ? (teacherPhones[normalizeKey(book.author[0])] ?? "")
                : "";
              if (!phone.replace(/[^\d+]/g, "")) {
                showNativeToast("Seller contact information is unavailable.");
                return;
              }
              setShowGetYoursDialog(true);
            }}
            onShare={() => {
              if (book) void shareResource("book", book.id, book.title);
            }}
            onBookmark={async () => {
              if (!book) return;

              if (!auth.currentUser?.uid) {
                setShowGuestSaveAlert(true);
                return;
              }

              try {
                await toggleSavedItem(
                  auth.currentUser.uid,
                  "saved-books",
                  book.id,
                  bookmarked,
                );
                setBookmarked((value) => !value);
                showNativeToast(
                  bookmarked
                    ? feedbackMessages.itemUnsaved
                    : feedbackMessages.itemSaved,
                );
              } catch (e) {
                console.error("Failed to toggle bookmark", e);
              }
            }}
          />
        </View>
      </View>

      <ActionDialog
        visible={showGuestSaveAlert}
        title="Save this resource"
        message="Log in or sign up to save books and resources for later."
        primaryText="Log in"
        secondaryText="Sign up"
        onPrimary={() =>
          router.push({
            pathname: "/login",
            params: {
              from:
                typeof returnTo === "string" && returnTo.trim()
                  ? returnTo
                  : "/",
            },
          } as any)
        }
        onSecondary={() =>
          router.push({
            pathname: "/signup",
            params: {
              from:
                typeof returnTo === "string" && returnTo.trim()
                  ? returnTo
                  : "/",
            },
          } as any)
        }
        onClose={() => setShowGuestSaveAlert(false)}
      />

      <ActionDialog
        visible={showGetYoursDialog}
        title="You're leaving OS platform"
        message="To get this book, you'll be redirected to an external service. Choose how you'd like to reach the seller."
        primaryText="WhatsApp"
        secondaryText="Phone Call"
        secondaryButtonColor={colors.primary}
        secondaryButtonTextColor="#fff"
        primaryButtonColor="#25D366"
        onPrimary={() => {
          const phone = book?.author.length
            ? (teacherPhones[normalizeKey(book.author[0])] ?? "")
            : "";
          const cleaned = phone.replace(/[^\d+]/g, "");
          if (!cleaned) return;
          Linking.openURL(
            `https://wa.me/${cleaned}?text=${encodeURIComponent(`Hi, I'm interested in the book "${book?.title}" from OS platform.`)}`,
          );
        }}
        onSecondary={() => {
          const phone = book?.author.length
            ? (teacherPhones[normalizeKey(book.author[0])] ?? "")
            : "";
          const cleaned = phone.replace(/[^\d+]/g, "");
          if (!cleaned) return;
          Linking.openURL(`tel:${cleaned}`);
        }}
        onClose={() => setShowGetYoursDialog(false)}
      />
    </Animated.View>
  );
}

