import { Image } from "expo-image";
import { useFocusEffect, useRouter } from "expo-router";
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  AppState,
  Pressable,
  StyleSheet,
  Text,
  useWindowDimensions,
  View,
} from "react-native";
import Animated, {
  Easing,
  FadeIn,
  FadeOut,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { colors, radius, spacing } from "../../constants/theme";
import { getThemeAsset } from "../../constants/themeAssets";
import { useTheme } from "../../contexts/ThemeContext";
import {
  getAssistantContent,
  getCachedAssistantMessage,
  isAssistantEnabled,
  setCachedAssistantMessage,
} from "../../services/aiAssistantService";

const TYPING_INTERVAL_MS = 32;
const MESSAGE_PAUSE_MS = 8000;
const MESSAGE_HIDDEN_MS = 40000;
const IDLE_FLOAT_DURATION_MS = 2600;
const MIN_TOUCH_SIZE = 44;

const getBubbleWidth = (width: number) =>
  Math.min(190, Math.max(150, width * 0.4));

export function FloatingAssistantButton() {
  const router = useRouter();
  const { isDark } = useTheme();
  const fallbackAvatar = getThemeAsset("panda", isDark);
  const { width } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const [isEnabled, setIsEnabled] = useState(true);

  useFocusEffect(
    useCallback(() => {
      let cancelled = false;
      isAssistantEnabled().then((val) => {
        if (!cancelled) {
          setIsEnabled(val);
        }
      });
      return () => {
        cancelled = true;
      };
    }, []),
  );
  const [messages, setMessages] = useState<string[]>([]);
  const [activeMessage, setActiveMessage] = useState(
    "Need help with your studies?",
  );
  const [avatarUri, setAvatarUri] = useState<string | null>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [isScreenActive, setIsScreenActive] = useState(
    AppState.currentState === "active",
  );

  const bubbleWidth = useMemo(() => getBubbleWidth(width), [width]);

  const scale = useSharedValue(0.92);
  const opacity = useSharedValue(0);
  const translateY = useSharedValue(16);
  const bubbleOpacity = useSharedValue(1);
  const bubbleScale = useSharedValue(1);
  const avatarTranslateY = useSharedValue(0);
  const typingIndex = useSharedValue(0);
  const currentMessage = useSharedValue(activeMessage);

  useEffect(() => {
    let cancelled = false;

    const loadData = async () => {
      try {
        const content = await getAssistantContent();
        if (cancelled) {
          return;
        }

        const cachedMessage = getCachedAssistantMessage();
        const initialMessage =
          cachedMessage ??
          content.messages[0] ??
          "Need help with your studies?";

        setMessages(content.messages);
        setActiveMessage(initialMessage);
        currentMessage.value = initialMessage;
        setAvatarUri(content.avatar ?? null);
        setIsVisible(true);

        opacity.value = withSpring(1, { damping: 18, stiffness: 120 });
        translateY.value = withSpring(0, { damping: 18, stiffness: 120 });
        scale.value = withSpring(1, { damping: 18, stiffness: 120 });
      } catch (error) {
        if (!cancelled) {
          setMessages(["Need help with your studies?"]);
          setActiveMessage("Need help with your studies?");
          currentMessage.value = "Need help with your studies?";
          setAvatarUri(null);
          setIsVisible(true);
        }
      }
    };

    loadData();

    return () => {
      cancelled = true;
    };
  }, [currentMessage, opacity, scale, translateY]);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (nextState) => {
      setIsScreenActive(nextState === "active");
    });

    return () => subscription.remove();
  }, []);

  useEffect(() => {
    if (!isVisible || messages.length === 0 || !isScreenActive) {
      return;
    }

    let visiblePauseTimeout: ReturnType<typeof setTimeout> | undefined;
    let hiddenPauseTimeout: ReturnType<typeof setTimeout> | undefined;
    let hideAnimationTimeout: ReturnType<typeof setTimeout> | undefined;
    let typingTimer: ReturnType<typeof setTimeout> | undefined;

    const animateMessageCycle = () => {
      const nextMessage = messages[Math.floor(Math.random() * messages.length)];
      if (!nextMessage) {
        return;
      }

      setCachedAssistantMessage(nextMessage);
      setActiveMessage("");
      currentMessage.value = nextMessage;
      typingIndex.value = 0;
      bubbleOpacity.value = 1;
      bubbleScale.value = 1;

      const typeCharacters = () => {
        if (!isScreenActive) {
          return;
        }

        if (typingIndex.value >= nextMessage.length) {
          visiblePauseTimeout = setTimeout(() => {
            bubbleOpacity.value = withTiming(0, {
              duration: 300,
              easing: Easing.in(Easing.ease),
            });
            bubbleScale.value = withTiming(0.96, {
              duration: 300,
              easing: Easing.in(Easing.ease),
            });
            hideAnimationTimeout = setTimeout(() => {
              hiddenPauseTimeout = setTimeout(() => {
                animateMessageCycle();
              }, MESSAGE_HIDDEN_MS);
            }, 400);
          }, MESSAGE_PAUSE_MS);
          return;
        }

        const visibleText = nextMessage.slice(0, typingIndex.value + 1);
        setActiveMessage(visibleText);
        typingIndex.value = typingIndex.value + 1;
        typingTimer = setTimeout(typeCharacters, TYPING_INTERVAL_MS);
      };

      typeCharacters();
    };

    animateMessageCycle();

    return () => {
      if (visiblePauseTimeout) {
        clearTimeout(visiblePauseTimeout);
      }
      if (hideAnimationTimeout) {
        clearTimeout(hideAnimationTimeout);
      }
      if (hiddenPauseTimeout) {
        clearTimeout(hiddenPauseTimeout);
      }
      if (typingTimer) {
        clearTimeout(typingTimer);
      }
    };
  }, [
    isVisible,
    messages,
    bubbleOpacity,
    bubbleScale,
    currentMessage,
    typingIndex,
    isScreenActive,
  ]);

  useEffect(() => {
    avatarTranslateY.value = withRepeat(
      withSequence(
        withTiming(-3, { duration: 1600, easing: Easing.inOut(Easing.ease) }),
        withTiming(3, { duration: 1600, easing: Easing.inOut(Easing.ease) }),
      ),
      -1,
      true,
    );
  }, [avatarTranslateY]);

  const animatedContainerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: translateY.value }, { scale: scale.value }],
  }));

  const animatedBubbleStyle = useAnimatedStyle(() => ({
    opacity: bubbleOpacity.value,
    transform: [{ scale: bubbleScale.value }],
  }));

  const animatedAvatarStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: avatarTranslateY.value }],
  }));

  const handlePressIn = () => {
    scale.set(withTiming(0.96, { duration: 120 }));
  };

  const handlePressOut = () => {
    scale.set(withTiming(1, { duration: 120 }));
  };

  const handlePress = () => {
    const fullMessage = currentMessage.value.trim();
    const isBubbleVisible = bubbleOpacity.value > 0.1 && fullMessage.length > 0;

    if (isBubbleVisible) {
      router.push({
        pathname: "/assistant",
        params: { initialPrompt: fullMessage },
      });
    } else {
      router.push("/assistant");
    }
  };

  if (!isEnabled) {
    return null;
  }

  return (
    <Animated.View
      entering={FadeIn.duration(600)}
      exiting={FadeOut.duration(220)}
      style={[
        styles.wrapper,
        { pointerEvents: "box-none" },
        { bottom: insets.bottom, right: 5, maxWidth: width - 32 },
      ]}
    >
      <Animated.View
        style={[
          styles.container,
          { pointerEvents: "box-none" },
          animatedContainerStyle,
        ]}
      >
        <Animated.View
          style={[
            styles.bubbleWrapper,
            { pointerEvents: "none" },
            animatedBubbleStyle,
          ]}
        >
          <View
            style={[
              styles.messageBubble,
              { pointerEvents: "none", maxWidth: bubbleWidth },
            ]}
          >
            <Text numberOfLines={2} style={styles.messageText}>
              {activeMessage}
            </Text>
          </View>
        </Animated.View>

        <Pressable
          accessibilityRole="button"
          accessibilityLabel="Open AI assistant"
          onPress={handlePress}
          onPressIn={handlePressIn}
          onPressOut={handlePressOut}
          style={({ pressed }) => [
            styles.touchTarget,
            pressed && styles.touchTargetPressed,
            {
              minHeight: MIN_TOUCH_SIZE,
              minWidth: MIN_TOUCH_SIZE,
            },
          ]}
        >
          <Animated.View style={[styles.avatarWrapper, animatedAvatarStyle]}>
            <View style={styles.avatarFrame}>
              <Image
                source={avatarUri ? { uri: avatarUri } : fallbackAvatar}
                placeholder={fallbackAvatar}
                contentFit="contain"
                style={styles.avatar}
              />
            </View>
          </Animated.View>
        </Pressable>
      </Animated.View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
