import { Image } from "expo-image";
import { useEffect, useRef, useState } from "react";
import { StyleSheet, View } from "react-native";
import { Skeleton } from "../ui/Skeleton";

interface PdfPreviewProps {
  uri: string;
  style: any;
  onLoad?: () => void;
  onError?: () => void;
  showLoadingIndicator?: boolean;
}

const loadPdfJs = () => {
  return new Promise<any>((resolve, reject) => {
    if ((window as any).pdfjsLib) {
      resolve((window as any).pdfjsLib);
      return;
    }
    const script = document.createElement("script");
    script.src =
      "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.min.js";
    script.onload = () => {
      const pdfjsLib = (window as any).pdfjsLib;
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.worker.min.js";
      resolve(pdfjsLib);
    };
    script.onerror = reject;
    document.head.appendChild(script);
  });
};

import { getThemeAsset } from "../../constants/themeAssets";
import { useTheme } from "../../contexts/ThemeContext";
import { useFirebaseStorageUrl } from "../../utils/firebaseStorage";

export default function PdfPreview({
  uri,
  style,
  onLoad,
  onError,
  showLoadingIndicator = true,
}: PdfPreviewProps) {
  const { isDark } = useTheme();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const resolvedUri = useFirebaseStorageUrl(uri) || uri;

  useEffect(() => {
    let active = true;
    if (
      !resolvedUri ||
      (!resolvedUri.startsWith("http://") &&
        !resolvedUri.startsWith("https://") &&
        !resolvedUri.startsWith("blob:") &&
        !resolvedUri.startsWith("data:"))
    ) {
      return;
    }

    loadPdfJs()
      .then(async (pdfjsLib) => {
        try {
          const loadingTask = pdfjsLib.getDocument({
            url: resolvedUri,
            withCredentials: false,
          });
          const pdf = await loadingTask.promise;
          if (!active) return;

          const page = await pdf.getPage(1);
          if (!active) return;

          const canvas = canvasRef.current;
          if (!canvas) return;

          const context = canvas.getContext("2d");
          if (!context) return;

          // Render at a high resolution for crispness, CSS will scale it down
          const viewport = page.getViewport({ scale: 1.5 });
          canvas.width = viewport.width;
          canvas.height = viewport.height;

          const renderContext = {
            canvasContext: context,
            viewport: viewport,
          };
          await page.render(renderContext).promise;
          if (active) {
            setLoading(false);
            onLoad?.();
          }
        } catch (err) {
          console.warn("Error rendering PDF on web:", err);
          if (active) {
            setError(true);
            setLoading(false);
            onError?.();
          }
        }
      })
      .catch((err) => {
        console.warn("Error loading PDF.js:", err);
        if (active) {
          setError(true);
          setLoading(false);
          onError?.();
        }
      });

    return () => {
      active = false;
    };
  }, [resolvedUri]);

  if (error) {
    return (
      <Image
        source={getThemeAsset("pdfPreview", isDark)}
        style={[style, styles.fallback]}
        contentFit="cover"
      />
    );
  }

  return (
    <View style={[style, styles.container]}>
      {loading && showLoadingIndicator && (
        <View
          style={StyleSheet.absoluteFill}
          className="justify-center items-center"
        >
          <Skeleton style={styles.loadingSkeleton} />
        </View>
      )}
      <canvas
        ref={canvasRef}
        style={{
          width: "100%",
          height: "100%",
          objectFit: "cover",
          objectPosition: "top center",
          display: loading ? "none" : "block",
        }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  fallback: { backgroundColor: "#D1D5DB" },
  loadingSkeleton: { width: "72%", height: 18, borderRadius: 5 },
  container: {
    overflow: "hidden",
    justifyContent: "flex-start",
    alignItems: "center",
    backgroundColor: "#f5f5f5",
  },
});

