  screen: {
    flex: 1,
  },

  // Header
  header: {
    height: 56,
    flexDirection: "row",
    alignItems: "center",
    paddingHorizontal: spacing.md,
    borderBottomWidth: 1,
    ...Platform.select({
      ios: {
        boxShadow: "0px 2px 6px rgba(15, 23, 42, 0.06)",
