    fontSize: 11,
    marginTop: 1,
  },

  // Download button
  downloadBtn: {
    borderRadius: radius.pill,
    ...Platform.select({
      ios: {
        boxShadow: "0px 3px 8px rgba(108, 99, 255, 0.35)",
      },
      android: { elevation: 6 },
    }),
  },
  downloadGradient: {
    paddingHorizontal: 16,
    paddingVertical: 8,
    borderRadius: radius.pill,
    justifyContent: "center",
    alignItems: "center",
  },
  downloadText: {
    color: "#FFFFFF",
    fontSize: 13,
    fontWeight: "500",
  },

  // Download Progress Banner
  downloadProgressBanner: {
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm,
    borderBottomWidth: 1,
    gap: 6,
  },
  downloadProgressInfo: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
  },
  downloadProgressLabel: {
    fontSize: 12,
    fontWeight: "600",
  },
  downloadTrack: {
    height: 4,
    borderRadius: 2,
    overflow: "hidden",
  },
  downloadFill: {
    height: 4,
    borderRadius: 2,
    overflow: "hidden",
  },

  // Progress bar
  progressTrack: {
    height: 3,
  },
  progressBar: {
    height: 3,
  },

  // WebView
  webview: {
    flex: 1,
