import { onAuthStateChanged, User } from "firebase/auth";
import { doc, onSnapshot } from "firebase/firestore";
import {
  createContext,
  ReactNode,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import { auth, db } from "../../firebaseConfig";
import {
  defaultUserProfile,
  ensureUserProfile,
  UserProfile,
} from "../services/userProfile";

type ProfileState = {
  user: User | null;
  profile: UserProfile | null;
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
};
const ProfileContext = createContext<ProfileState | undefined>(undefined);

export function ProfileProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(auth.currentUser);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(
    () =>
      onAuthStateChanged(auth, (nextUser) => {
        setUser(nextUser);
        setProfile(null);
        setError(null);
        setLoading(Boolean(nextUser));
      }),
    [],
  );
  useEffect(() => {
    if (!user) {
      setLoading(false);
      return;
    }
    let active = true;
    let usersSnapshotReceived = false;
    let teachersSnapshotReceived = false;
    let usersData: Record<string, unknown> | null = null;
    let teachersData: Record<string, unknown> | null = null;

    const updateProfile = () => {
      if (!active || (!usersSnapshotReceived && !teachersSnapshotReceived))
        return;
      const data = teachersData ?? usersData;
      setProfile(
        data
          ? ({
              ...defaultUserProfile(user),
              ...usersData,
              ...teachersData,
            } as UserProfile)
          : null,
      );
      setLoading(false);
    };
    const handleError = (reason: Error) => {
      if (!active) return;
      setError(reason.message || "Could not load your profile.");
      setLoading(false);
    };

    const unsubscribeUsers = onSnapshot(
      doc(db, "users", user.uid),
      (snapshot) => {
        usersSnapshotReceived = true;
        usersData = snapshot.exists()
          ? (snapshot.data() as Record<string, unknown>)
          : null;
        updateProfile();
      },
      handleError,
    );
    const unsubscribeTeachers = onSnapshot(
      doc(db, "teachers", user.uid),
      (snapshot) => {
        teachersSnapshotReceived = true;
        teachersData = snapshot.exists()
          ? (snapshot.data() as Record<string, unknown>)
          : null;
        updateProfile();
      },
      handleError,
    );

    return () => {
      active = false;
      unsubscribeUsers();
      unsubscribeTeachers();
    };
  }, [user]);
  const refresh = async () => {
    if (user) await ensureUserProfile(user);
  };
  const value = useMemo(
    () => ({ user, profile, loading, error, refresh }),
    [user, profile, loading, error],
  );
  return (
    <ProfileContext.Provider value={value}>{children}</ProfileContext.Provider>
  );
}
export function useProfile() {
  const state = useContext(ProfileContext);
  if (!state) throw new Error("useProfile must be used within ProfileProvider");
  return state;
}

import Constants from "expo-constants";
import {
  deleteUser,
  FacebookAuthProvider,
  GoogleAuthProvider,
  signInWithCredential,
  signInWithPopup,
  User,
  UserCredential,
} from "firebase/auth";
import { NativeModules, Platform, TurboModuleRegistry } from "react-native";
import { auth } from "../../firebaseConfig";

export interface SocialAuthResult {
  success: boolean;
  user?: UserCredential["user"];
  error?: string;
  cancelled?: boolean;
}

async function requireVerifiedUser(
  user: User,
): Promise<SocialAuthResult | null> {
  if (user.emailVerified) return null;

  try {
    await deleteUser(user);
  } catch {}

  return {
    success: false,
    error:
      "Your email must be verified before you can create a OS platform account.",
  };
}

/**
 * Safely checks if the native GoogleSignin TurboModule/NativeModule exists
 * to prevent Expo Go from crashing with Invariant Violation on module load.
 */
function isNativeGoogleSigninAvailable(): boolean {
  if (Platform.OS === "web") return false;
  try {
    if (NativeModules && NativeModules.RNGoogleSignin) {
      return true;
    }
    if (
      typeof TurboModuleRegistry !== "undefined" &&
      typeof TurboModuleRegistry.get === "function"
    ) {
      return Boolean(TurboModuleRegistry.get("RNGoogleSignin"));
    }
    return false;
  } catch {
    return false;
  }
}

/**
 * Dynamically loads and configures GoogleSignin only if the native binary is present.
 */
function getNativeGoogleSigninModule() {
  if (!isNativeGoogleSigninAvailable()) {
    return null;
  }
  try {
    const mod = require("@react-native-google-signin/google-signin");
    if (
      mod &&
      mod.GoogleSignin &&
      typeof mod.GoogleSignin.configure === "function"
    ) {
      const extra =
        (Constants.expoConfig?.extra as Record<string, any> | undefined) ?? {};
      const webClientId =
        process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID ||
        extra.googleWebClientId ||
        "";

      mod.GoogleSignin.configure({
        webClientId: webClientId || undefined,
        scopes: ["profile", "email"],
        offlineAccess: true,
      });
    }
    return mod;
  } catch {
    return null;
  }
}

export function parseAuthError(error: unknown): string {
  const message =
    typeof error === "string"
      ? error
      : error &&
          typeof error === "object" &&
          "message" in error &&
          typeof error.message === "string"
        ? error.message
        : "";

  if (
    /app not active|app is not accessible right now|app developer is aware/i.test(
      message,
    )
  ) {
    return "Facebook Login is unavailable because the Meta app is inactive. Reactivate the app in Meta for Developers, then try again.";
  }

  if (/deleted_client|OAuth client was deleted/i.test(message)) {
    return "Google Sign-In is temporarily unavailable because its OAuth client was deleted. Please contact support.";
  }

  if (error && typeof error === "object" && "code" in error) {
    const code = (error as { code: string }).code;
    switch (code) {
      case "auth/popup-closed-by-user":
      case "auth/cancelled-popup-request":
      case "ERR_REQUEST_CANCELED":
      case "dismiss":
        return "Authentication was cancelled.";
      case "auth/popup-blocked":
        return "Your browser blocked the sign-in window. Please allow pop-ups for OS platform and try again.";
      case "auth/account-exists-with-different-credential":
        return "An account already exists with this email using a different sign-in method.";
      case "auth/network-request-failed":
        return "Couldn't connect. Please check your internet connection and try again.";
      case "auth/user-disabled":
        return "This account has been disabled. Please contact support.";
      case "auth/invalid-credential":
        return "Invalid credentials. Please try signing in again.";
      default:
        return "Authentication failed. Please try again.";
    }
  }
  return "Authentication failed. Please try again.";
}

/**
 * Signs in or signs up a user using Google Authentication.
 * - On Web: uses Firebase signInWithPopup.
 * - On Native Development Build / Standalone APK: uses native Google Play Services.
 * - On Expo Go: cleanly informs the user that native Google Sign-in requires a dev build.
 */
export async function signInWithGoogle(): Promise<SocialAuthResult> {
  try {
    if (Platform.OS === "web") {
      const provider = new GoogleAuthProvider();
      provider.addScope("profile");
      provider.addScope("email");
      const credential = await signInWithPopup(auth, provider);
      const verificationError = await requireVerifiedUser(credential.user);
      if (verificationError) return verificationError;
      return { success: true, user: credential.user };
    }

    // Native mobile flow
    const googleModule = getNativeGoogleSigninModule();

    if (!googleModule) {
      return {
        success: false,
        error:
          "Google Sign-In on mobile requires native Google Play Services (available in a Development Build or standalone APK). Please use the email sign-in link in Expo Go.",
      };
    }

    const { GoogleSignin, statusCodes, isErrorWithCode, isSuccessResponse } =
      googleModule;

    await GoogleSignin.hasPlayServices({ showPlayServicesUpdateDialog: true });
    const response = await GoogleSignin.signIn();

    let idToken: string | undefined | null;
    if (
      typeof isSuccessResponse === "function" &&
      isSuccessResponse(response)
    ) {
      idToken = response.data?.idToken;
    } else if (response && response.data && response.data.idToken) {
      idToken = response.data.idToken;
    } else if (response && response.idToken) {
      idToken = response.idToken;
    }

    if (!idToken && typeof GoogleSignin.getTokens === "function") {
      const tokens = await GoogleSignin.getTokens();
      idToken = tokens?.idToken;
    }

    if (!idToken) {
      return {
        success: false,
        error:
          "Unable to retrieve Google identification token. Please try again.",
      };
    }

    const credential = GoogleAuthProvider.credential(idToken);
    const userCredential = await signInWithCredential(auth, credential);
    const verificationError = await requireVerifiedUser(userCredential.user);
    if (verificationError) return verificationError;
    return { success: true, user: userCredential.user };
  } catch (error: any) {
    const googleModule = getNativeGoogleSigninModule();
    if (
      googleModule &&
      typeof googleModule.isErrorWithCode === "function" &&
      googleModule.isErrorWithCode(error)
    ) {
      const { statusCodes } = googleModule;
      switch (error.code) {
        case statusCodes.SIGN_IN_CANCELLED:
          return { success: false, cancelled: true };
        case statusCodes.IN_PROGRESS:
          return {
            success: false,
            error: "Google sign-in is already in progress.",
          };
        case statusCodes.PLAY_SERVICES_NOT_AVAILABLE:
          return {
            success: false,
            error:
              "Google Play Services is unavailable or outdated on this device.",
          };
        default:
          return {
            success: false,
            error: parseAuthError(error),
          };
      }
    }

    const errorMsg = parseAuthError(error);
    if (
      errorMsg.includes("cancelled") ||
      error?.code === "auth/popup-closed-by-user" ||
      error?.code === "auth/cancelled-popup-request"
    ) {
      return { success: false, cancelled: true };
    }
    return { success: false, error: errorMsg };
  }
}

/**
 * Signs in or signs up a user using Facebook Authentication.
 */
export async function signInWithFacebook(): Promise<SocialAuthResult> {
  try {
    const provider = new FacebookAuthProvider();
    provider.addScope("email");
    provider.addScope("public_profile");
    const credential = await signInWithPopup(auth, provider);
    const verificationError = await requireVerifiedUser(credential.user);
    if (verificationError) return verificationError;
    return { success: true, user: credential.user };
  } catch (error: any) {
    const errorMsg = parseAuthError(error);
    if (
      errorMsg.includes("cancelled") ||
      error?.code === "auth/popup-closed-by-user" ||
      error?.code === "auth/cancelled-popup-request"
    ) {
      return { success: false, cancelled: true };
    }
    return { success: false, error: errorMsg };
  }
}
